-- Resources content for retiring Sourcework's theme model and Draft with AI (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema. Depends on 20261026120000 only in that the screens it describes are gone.

select private.rc_release_guide(
  p_slug => 'sourcework-pieces',
  p_tool_key => 'transcription',
  p_title => 'Building a piece from narration and excerpts',
  p_summary => 'Write a wrap, voicer or feature block by block, or draft it from a format, then edit by hand or with the assistant. Every version is kept.',
  p_screen_keys => array['sourcework.pieces', 'sourcework.piece'],
  p_sort_order => 18,
  p_version_note => 'Draft with AI is replaced by Outline with AI',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece is a reader, voicer, wrap, spot or feature you build from your own narration and the project's excerpts. It starts blank. You can write it block by block, or let AI outline it from your accepted findings, write the outline out as narration, and then edit it by hand or with the assistant."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a piece"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project, select "},{"type":"text","text":"Pieces","marks":[{"type":"bold"}]},{"type":"text","text":", pick a format if you want one (or leave it on No format), then "},{"type":"text","text":"+ New piece","marks":[{"type":"bold"}]},{"type":"text","text":". The editor opens at once on an empty piece with its title ready to type. The Pieces list shows each piece's length and when it last changed."}]},{"type":"paragraph","content":[{"type":"text","text":"A format sets the piece's target length and gives you a guide to write by. You can choose or change it any time from "},{"type":"text","text":"Format","marks":[{"type":"bold"}]},{"type":"text","text":" under the length at the top of the piece, and "},{"type":"text","text":"Show guide","marks":[{"type":"bold"}]},{"type":"text","text":" shows its description. The guide is a reminder of what the format usually asks for; it doesn't stop you doing something else. Choosing a format doesn't change what you've written."}]},{"type":"paragraph","content":[{"type":"text","text":"The formats are Reader / Voicer (about 0:30 to 0:45, no recorded excerpts), Cut and Copy (0:45, one excerpt), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). The excerpt counts are a usual range, not a requirement: a strong piece can use fewer."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outline and write it out (optional)"}]},{"type":"paragraph","content":[{"type":"text","text":"On an empty piece, choose "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":". It plans the story as beats, with your excerpts placed where they belong, from the findings you have accepted. A piece with beats shows "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":", which turns each beat into narration in place. Both are versions you can undo, and nothing is written until you ask. The Outline a piece guide has the details."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add narration and excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Narration","marks":[{"type":"bold"}]},{"type":"text","text":". Write in a narration block. Press Enter at the end of a block to add another below it, and Shift+Enter for a new line. Backspace in an empty block removes it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts","marks":[{"type":"bold"}]},{"type":"text","text":". Between every block, and before the first and after the last, there is a + row. Select it and choose Excerpt to search the project's audio excerpts by title, words, speaker or source. Arrow keys move through the results and Enter adds one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An excerpt's words always come from the transcript for the clip you hear. They cannot be retyped in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a block"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside a block for "},{"type":"text","text":"Move up","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Move down","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Mark as anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" (on narration), "},{"type":"text","text":"Swap excerpt…","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" and removal. On a desktop you can also drag the ⋮⋮ handle to reorder."}]},{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"anchor intro","marks":[{"type":"bold"}]},{"type":"text","text":" is the lead-in the anchor reads before a reporter's recorded piece. It is shown as its own block and isn't counted in the piece's length, so a 0:53 wrap stays 0:53 whatever the intro adds. Reader, voicer and cut and copy copy is part of the piece and is timed with it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Trim a clip in place"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Trim…","marks":[{"type":"bold"}]},{"type":"text","text":" on an excerpt block. The clip's words appear in their transcript context. Tap a word to move the nearer end of the clip there, or nudge the start and end with the −250, −50, +50 and +250 buttons. "},{"type":"text","text":"Play as cut","marks":[{"type":"bold"}]},{"type":"text","text":" plays what you have."}]},{"type":"paragraph","content":[{"type":"text","text":"By default a trim belongs to this piece only and the excerpt itself is unchanged. Choose "},{"type":"text","text":"Update the excerpt everywhere","marks":[{"type":"bold"}]},{"type":"text","text":" to change the excerpt itself; the panel says how many other pieces use it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Length"}]},{"type":"paragraph","content":[{"type":"text","text":"The length at the top adds up narration, estimated at 160 words a minute, and the clips' own running time, without any anchor intro. Choosing a format sets a target; select "},{"type":"text","text":"Change target","marks":[{"type":"bold"}]},{"type":"text","text":" to use a different one. The piece shows how far under or over it is."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ask the assistant"}]},{"type":"paragraph","content":[{"type":"text","text":"Open the assistant from "},{"type":"text","text":"Assistant","marks":[{"type":"bold"}]},{"type":"text","text":" at the top of the piece (on a phone, the bar at the bottom). It knows which piece you have open and says so at the top: “Working in: …”. Ask it to tighten a passage, move a quote, trim a clip, add a line, or outline the piece again. Anything you have typed is saved before your message goes."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It changes only what you ask, and says what it changed. Its reply lists the tools it used."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It places and swaps excerpts by id. It can't change what a speaker said, and the lengths it reports come from the same arithmetic as the screen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each block it changed is marked "},{"type":"text","text":"Edited by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Added by the assistant","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Undo","marks":[{"type":"bold"}]},{"type":"text","text":" on the mark puts that block back. The marks stay until you next edit the piece yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a + row, Ask the assistant to write it opens the assistant with a request for narration at that spot, for you to finish and send."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Saving and history"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece saves itself a moment after you stop typing. Every save is a version, including each change the assistant makes and every outline or write-out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists the versions with who saved each one, and whether it was you, an outline or a write-out, or the assistant. Restore saves an earlier version again as the newest, so nothing is lost."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If someone else saves the piece while you are editing, you are asked to reload instead of overwriting their work."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Take it with you"}]},{"type":"paragraph","content":[{"type":"text","text":"Copy as text","marks":[{"type":"bold"}]},{"type":"text","text":" copies the narration and the quoted words, with each clip's length and the total running time. "},{"type":"text","text":"Export excerpts","marks":[{"type":"bold"}]},{"type":"text","text":" downloads every excerpt in the project as one zip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only audio and video excerpts can go in a piece. Document excerpts have no sound."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an excerpt is deleted after it was used, its block says so and can be swapped or removed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything on a piece works on a phone: menus and the + picker open as sheets, and Move up and Move down replace dragging."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outlining, writing out and the assistant send the piece's material (accepted findings and the excerpts' words) to an outside service, as analysis does. Building a piece by hand doesn't."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Pieces list says how each piece was made: Written by hand, or the format it was written from, then edited."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-piece-formats',
  p_tool_key => 'transcription',
  p_title => 'Maintaining piece formats',
  p_summary => 'For editors: the length, actualities, description and style a piece format asks for. Edit, try a draft on a project, publish and roll back.',
  p_screen_keys => array['sourcework.formats'],
  p_sort_order => 21,
  p_version_note => 'Formats guide outlines',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece format is the shape and wording an outline, and writing the outline out, follow: its length, how many actualities it usually uses, a free-text description and style, and whether an anchor leads in. These are guardrails: the model decides the beats and chooses the actualities freely from the material, so every story can take its own shape. Editors maintain formats; you need the Editor role on Sourcework, which an administrator grants on the user's access screen."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a format"}]},{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Prompts and formats","marks":[{"type":"bold"}]},{"type":"text","text":" from the Projects page and choose "},{"type":"text","text":"Piece formats","marks":[{"type":"bold"}]},{"type":"text","text":". Pick a format on the left (on a phone, from the list at the top). Your changes save themselves as a draft only you can see."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Length","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Plus or minus","marks":[{"type":"bold"}]},{"type":"text","text":": the length the piece should run and the range that counts as on target, such as 0:53 within 0:08, which is 0:45 to 1:01."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Usual actualities","marks":[{"type":"bold"}]},{"type":"text","text":": the fewest and most clips the piece usually uses. It is a guide, not a quota: an outline may use fewer, and only going over the most is flagged in a trial."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Description and style","marks":[{"type":"bold"}]},{"type":"text","text":": what the piece does and how it sounds, such as who reads it and what a listener should come away with. Write placeholders the reporter fills in, such as [REPORTER NAME], in square brackets. Don’t lay out its blocks or their order: the model decides how many beats the story needs and where the actualities go. Tick "},{"type":"text","text":"An anchor may read a lead-in first","marks":[{"type":"bold"}]},{"type":"text","text":" for formats where the anchor can introduce a reporter’s recorded piece. It is always optional, since a piece the anchor reads itself has none, and it isn’t counted in the length."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The model writes beats, and narration when an outline is written out; actualities are always the project's own excerpts. A format can't change that, and it can't make the model type out a quote."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Try a draft"}]},{"type":"paragraph","content":[{"type":"text","text":"Try this draft","marks":[{"type":"bold"}]},{"type":"text","text":" outlines a piece from one project's accepted findings and excerpts with your draft and with the live version, and shows the two side by side with how many beats and actualities each used and how much clip time. Add a direction if you want to test one. Nothing is added to the project, and results are kept for 14 days and are visible only to you."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish and roll back"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Publish… asks for a one-line note about what changed, then makes the draft the live version. Reporters' next outlines follow it; pieces already outlined keep the version they followed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"History lists every version with its note and how many pieces it made. Edit from this version starts a draft from it, and Make live again moves an earlier version back into use. Nothing is deleted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"+ New format adds a format. It isn't offered to reporters until you publish it. Rename changes its name everywhere."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The formats to start with"}]},{"type":"paragraph","content":[{"type":"text","text":"Five formats come built in, each a description and a set of guardrails: Reader / Voicer (about 0:30 to 0:45, no actualities), Cut and Copy (0:45, one actuality), Wrap (about 0:45 to 1:00, one or two), Super Spot (2:00, one to three) and Feature (4:00, two to six). Anything else, such as a two-way or an interview, is a format you can add. Change the built-in ones like any other format."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-synthesis',
  p_tool_key => 'transcription',
  p_title => 'Synthesis',
  p_summary => 'Read what a project''s accepted findings establish for each research question, where accounts conflict and what is still open.',
  p_screen_keys => array['sourcework.synthesis'],
  p_sort_order => 20,
  p_version_note => 'Themes are retired',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis reads every finding you have accepted in a project and says what they establish about each of your research questions: what is established, what is contested, what is uncertain, where accounts conflict and what the sources leave open. It is a reading aid. Every statement opens onto the findings behind it, and nothing in it is evidence on its own."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Write a synthesis"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a project and select "},{"type":"text","text":"Synthesis","marks":[{"type":"bold"}]},{"type":"text","text":". The tab appears once the project has an accepted finding."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"Synthesize","marks":[{"type":"bold"}]},{"type":"text","text":". One run reads all the accepted findings together. It can take a few minutes, because the model may search the transcripts to check a finding that looks thin or two that seem to conflict. You can leave the tab open and come back."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A project with no research question gets one section for all its findings. Questions on the Setup tab give each one its own section."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How to read it"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Established","marks":[{"type":"bold"}]},{"type":"text","text":" means independent sources, or a firsthand account and a record, agree. "},{"type":"text","text":"Contested","marks":[{"type":"bold"}]},{"type":"text","text":" means credible findings conflict. "},{"type":"text","text":"Uncertain","marks":[{"type":"bold"}]},{"type":"text","text":" means the support is thin, secondhand or unconfirmed. Several findings from one source count as one source’s account, and the line under each statement says how many findings, sources and speakers stand behind it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the line under a statement to read the findings behind it and listen to where each was said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where accounts conflict","marks":[{"type":"bold"}]},{"type":"text","text":" lists real disagreements: an official account against a firsthand one, a memory against a record, a figure that changed. Each side shows its position and its findings."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Still open","marks":[{"type":"bold"}]},{"type":"text","text":" names what a reporter could go and get before relying on a statement."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Worth hearing","marks":[{"type":"bold"}]},{"type":"text","text":" points at moments in the recordings that a paraphrase would lose. They are not findings; open one to listen."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Keeping it current"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When findings change after a version was written, the tab says how many. "},{"type":"text","text":"Update synthesis","marks":[{"type":"bold"}]},{"type":"text","text":" writes a new version from the current findings."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every run writes a new version and keeps the earlier ones. Open an earlier version under Earlier versions to read it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A statement whose findings you have since rejected is marked as having no accepted finding behind it, so you can see what no longer holds."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis uses only accepted findings, never suggestions you have not reviewed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The text of every statement is the model’s wording. To use a speaker’s own words, make an excerpt."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'sourcework-accept-in-bulk',
  p_tool_key => 'transcription',
  p_title => 'Accepting suggestions in bulk',
  p_summary => 'Accept every finding waiting in a source at once instead of one by one.',
  p_screen_keys => array['sourcework.source'],
  p_sort_order => 24,
  p_version_note => 'Themes and quotes are retired',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When Analyze suggests a lot of findings from one source, you do not have to decide on each one separately. The source's Data points panel has an accept-all button. It asks you to confirm first, because you are deciding on many things without reading each."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Findings"}]},{"type":"paragraph","content":[{"type":"text","text":"On a source, with the To review filter showing, "},{"type":"text","text":"Accept all","marks":[{"type":"bold"}]},{"type":"text","text":" accepts every finding in that source still waiting for review. Findings you have already decided on are left as they are."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Taking a decision back"}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing is deleted by accepting. A finding can be rejected or put back for review afterwards."}]}]}$body$
);

-- The Themes and Suggested quotes guides describe screens that no longer exist. Deleting a guide removes its
-- versions and its links from release notes; the notes themselves stay as history.
delete from rc_articles where kind = 'guide' and slug in ('sourcework-themes', 'sourcework-suggested-quotes');

select private.rc_release_note(
  p_slug => 'release-2026-10-26-sourcework-themes-retired',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-26',
  p_title => 'Sourcework: Themes and Draft with AI are retired',
  p_guide_slugs => array['sourcework-pieces','sourcework-piece-formats','sourcework-synthesis','sourcework-accept-in-bulk','sourcework-outline'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework now works from Analyze to Synthesis to Outline. The Themes tab and theme pages are gone, and so is Draft with AI: on an empty piece, "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":" plans the story from your accepted findings, and "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":" turns each beat into narration. Trying a format now outlines a piece. Clips Analyze suggests are decided on the source's own page. Themes and earlier quote suggestions from the previous workflow have been removed."}]}]}$body$
);
